{"policy":"permit (
    principal is User,
    action == Action::"reviewPullRequest",
    resource is PullRequest
)
when {
    principal.roles.contains(resource.designatedRole)
};

forbid (
    principal is User,
    action == Action::"reviewPullRequest",
    resource is PullRequest
)
when {
    principal == resource.author &&
    resource.linesChanged < context.extraScrutinyLineThreshold
};

permit (
    principal is User,
    action == Action::"mergePullRequest",
    resource is PullRequest
);

forbid (
    principal is User,
    action == Action::"mergePullRequest",
    resource is PullRequest
)
when {
    principal == resource.author
};"}
